/* One entry stub per interrupt vector, all 256, generated by macros.
 *
 * Every stub ends up with the same stack layout so C sees one struct:
 *   - vectors where the CPU pushes an error code: leave it where it is;
 *   - all others: push a dummy 0 in its place;
 *   then push the vector number and jump to isr_common,
 *   which saves every general register and calls interrupt_dispatch(struct isr_frame *).
 *
 * The kernel is built with -mno-sse -mno-80387 -mno-red-zone,
 * so handlers need no FPU/SSE state saving and the interrupt frame cannot clobber a red zone.
 * If you ever enable SSE, this file must save that state too. */

.altmacro

.macro isr_stub n
isr_stub_\n:
    .if (\n == 8) || (\n >= 10 && \n <= 14) || (\n == 17) || (\n == 21) || (\n == 29) || (\n == 30)
    .else
        pushq $0
    .endif
    pushq $\n
    jmp isr_common
.endm

.macro isr_ptr n
    .quad isr_stub_\n
.endm

    .section .text

isr_common:
    pushq %rax
    pushq %rbx
    pushq %rcx
    pushq %rdx
    pushq %rsi
    pushq %rdi
    pushq %rbp
    pushq %r8
    pushq %r9
    pushq %r10
    pushq %r11
    pushq %r12
    pushq %r13
    pushq %r14
    pushq %r15

    movq %rsp, %rdi         /* argument: struct isr_frame * */
    cld                     /* the C ABI wants the direction flag clear */
    call interrupt_dispatch

    popq %r15
    popq %r14
    popq %r13
    popq %r12
    popq %r11
    popq %r10
    popq %r9
    popq %r8
    popq %rbp
    popq %rdi
    popq %rsi
    popq %rdx
    popq %rcx
    popq %rbx
    popq %rax

    addq $16, %rsp          /* drop the vector and the error code */
    iretq

.set i, 0
.rept 256
    isr_stub %i
    .set i, i+1
.endr

/* Table of the 256 stub addresses, read by idt_init(). */
    .section .rodata
    .balign 8
    .globl isr_stub_table
isr_stub_table:
.set i, 0
.rept 256
    isr_ptr %i
    .set i, i+1
.endr

/* No executable stack requested. */
    .section .note.GNU-stack,"",@progbits
